#include <bits/stdc++.h>
using namespace std;

vector<int> read_input() {
    vector<int> v;
    int x;
    while (cin >> x) {
        v.push_back(x);
        if (cin.peek() == '\n' || cin.eof()) break;
    }
    return v;
}

long long fast_pow(long long base, long long exp, long long mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    vector<int> input_vals = read_input();
    int p = input_vals[0];
    int k = input_vals[1];
    const long long MOD = 1000000007;
    long long result = 0;

    if (k == 0) {
        result = fast_pow(p, p - 1, MOD);
    } else {
        for (int i = 1; i < p; ++i) {
            if ((p - 1) % i == 0 && fast_pow(k, i, p) == 1) {
                result = fast_pow(p, (p - 1) / i, MOD);
                if (k == 1) {
                    result = (result * p) % MOD;
                }
                break;
            }
        }
    }
    cout << result << "\n";
    return 0;
}
